 const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const DAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
function lerp(a, b, t) { return a + (b - a) * t; }
function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
function mix(a, b, t) {
    const c = (x, y) => Math.round(x + (y - x) * t);
    return (c((a >> 16) & 255, (b >> 16) & 255) << 16) | (c((a >> 8) & 255, (b >> 8) & 255) << 8) | c(a & 255, b & 255);
}
function monthName(m) { return MONTHS[m - 1]; }
function dowName(i) { return DAYS[i].slice(0, 3); }
function dayKey(y, m, d) { return y + "-" + m + "-" + d; }
function keyOf(dt) { return dayKey(dt.getFullYear(), dt.getMonth() + 1, dt.getDate()); }
function parseKey(k) { const p = k.split("-").map(Number); return new Date(p[0], p[1] - 1, p[2]); }
function shortTime(min) {
    const h = Math.floor(min / 60), mm = min % 60, ap = h < 12 ? "a" : "p";
    const hh = h % 12 == 0 ? 12 : h % 12;
    return mm == 0 ? hh + ap : hh + ":" + (mm < 10 ? "0" + mm : "" + mm) + ap;
}
function hourLabel(h) { return (h % 12 == 0 ? 12 : h % 12) + (h < 12 ? " AM" : " PM"); }
function weekLabel(k) {
    const d = parseKey(k);
    const s = new Date(d.getFullYear(), d.getMonth(), d.getDate() - d.getDay());
    const e = new Date(s.getFullYear(), s.getMonth(), s.getDate() + 6);
    return monthName(s.getMonth() + 1) + " " + s.getDate() + " – "
        + (s.getMonth() == e.getMonth() ? "" : monthName(e.getMonth() + 1) + " ") + e.getDate();
}
function dayLabel(k) { const d = parseKey(k); return DAYS[d.getDay()] + ", " + monthName(d.getMonth() + 1) + " " + d.getDate(); } /*$b*/ return { MONTHS, DAYS, lerp, clamp, mix, monthName, dowName, dayKey, keyOf, parseKey, shortTime, hourLabel, weekLabel, dayLabel };

